<?php
 namespace QQWorld\Braintree\Gateway\Request; use QQWorld\Braintree\Gateway\Helper\SubjectReader; use QQWorld\Payment\Gateway\Request\BuilderInterface; use QQWorld\Payment\Helper\Formatter; class VaultCaptureDataBuilder implements BuilderInterface { use Formatter; private $subjectReader; public function __construct(SubjectReader $subjectReader) { $this->subjectReader = $subjectReader; } public function build(array $buildSubject) { $paymentDO = $this->subjectReader->readPayment($buildSubject); $payment = $paymentDO->getPayment(); $extensionAttributes = $payment->getExtensionAttributes(); $paymentToken = $extensionAttributes->getVaultPaymentToken(); return [ 'amount' => $this->formatPrice($this->subjectReader->readAmount($buildSubject)), 'paymentMethodToken' => $paymentToken->getGatewayToken() ]; } } 